import {lessonDepth} from './learning-depth.js';
import {qualityHelp} from './quality-questions.js';
export const guidance={
 'c-address':{conclusion:'x 是内容，&x 是位置；问的是两件不同的事。',oral:'变量有类型、值和地址。x 读取变量的值，&x 取得这个变量的地址。给 x 赋值会修改它的内容；在对象存活期间，这不意味着把对象搬到另一个位置。',terms:[['地址','一个对象在内存中的位置。'],['对象','程序中保存数据的一块存储区域，这里可以先理解为变量对应的空间。']]},
 'c-pointer-declare':{conclusion:'指针也是变量，只是它保存的值是地址。',oral:'int *p = &x 声明一个指向 int 的指针 p，用 x 的地址初始化它。p 保存的地址、p 自己的地址 &p，以及目标的值 *p，是三个不同概念。只有指针指向有效对象时，才可以通过它访问目标。',terms:[['指针','保存地址的变量。'],['初始化','创建对象时给它第一个值。']]},
 'c-dereference':{conclusion:'*p 访问的是 p 当前指向的对象，先找位置，再读写内容。',oral:'声明中的星号表示指针类型；表达式中的星号是解引用运算符。*p 出现在赋值左边时，会写入所指对象；用于读取时，得到所指对象的当前值。使用前要确认 p 有效、目标仍存活，且访问类型正确。',terms:[['解引用','沿指针保存的地址访问目标。'],['悬空指针','目标已经不再存活，但指针还留着原来的地址。']]},
 'c-pointer-change':{conclusion:'p = 改指针保存的地址；*p = 改当前目标的内容。',oral:'判断指针赋值先看等号左边。p = &b 修改的是指针 p，让它换一个目标；*p = 9 修改的是当前目标。必须按语句顺序追踪 p 指向谁，不能看到星号就认定它总是修改最初的变量。',terms:[['指向','指针保存了某个对象的地址。'],['赋值','把右边算出的值写入左边指定的对象。']]},
 'c-sizeof':{conclusion:'sizeof 求存储大小，单位是 C 字节，不是变量的数值。',oral:'sizeof 是运算符，结果类型是 size_t。对完整数组求的是整个数组大小，对指针求的是指针自身大小。具体类型大小要结合 ABI 和编译器；sizeof(char) 恒为 1 个 C 字节。普通非变长类型的 sizeof 操作数不求值。',terms:[['运算符','对数据执行一种操作的语言符号或关键字。'],['ABI','编译后的程序互相配合时遵循的约定，包括类型大小和函数调用规则。'],['size_t','用于表示对象大小的无符号整数类型。']]},
 'c-array-start':{conclusion:'数组保存多个同类型元素；下标从 0 开始，最后是数量减 1。',oral:'数组元素连续存放，int a[3] 有三个元素，有效下标是 0 到 2。常见表达式中 a 转换为首元素指针，但数组本身不是指针变量。对完整数组求 sizeof 得到总空间，访问之前还要检查下标范围。',terms:[['下标','元素在数组中的编号，从 0 开始。'],['数组退化','在多数表达式里，数组转换成指向首元素的指针。']]},
 'c-function-start':{conclusion:'C 的参数按值传递；复制地址后，仍能沿地址访问原对象。',oral:'传整数时，形参得到整数副本，修改形参不会直接改变调用者变量。传地址时，指针形参得到地址副本；通过它解引用可以修改调用者的对象，但给这个指针形参重新赋地址，仍只改变形参自己。',terms:[['形参','函数内部用来接收本次输入的变量。'],['实参','调用函数时实际提供的表达式或数据。'],['按值传递','把输入的值复制给函数形参。']]},
 'c-pointer':{conclusion:'指针加 1 跨过一个所指类型的对象，不一定跨一个字节。',oral:'指针算术的步长由所指类型决定。int *p 加一会移动 sizeof(int) 字节；只应在同一数组及其尾后一位内进行规定的算术。尾后指针可用于边界比较，但不能解引用。',terms:[['尾后指针','指向最后一个元素之后的位置，这个位置没有可访问的数组元素。']]}
};
const moduleHints={
 c:['先区分类型、值与地址，确认赋值左边究竟访问谁。','在纸上给每个变量单独列一格，按语句顺序更新；遇到 sizeof 或宏，先写出适用规则，不急着算结果。'],
 cpp:['先看对象何时创建、复制和销毁，以及表达式的静态类型。','列出对象与资源的归属，再按调用顺序检查构造、赋值、析构；有多态时分开判断静态类型和实际对象。'],
 memory:['先分清对象存放位置、生命周期和具体平台约定。','列出对象所属区域与存活范围，再核对题目给定的大小、对齐和访问条件。'],
 arm:['先判断这是普通指令执行、函数调用还是异常进入。','按寄存器变化与控制流顺序推演；中断问题先区分硬件保存与软件保存。'],
 ds:['先明确结构的有效范围与需要保持的规则。','用最小输入手算一次，再检查空输入、单元素和边界；复杂度分别数循环次数与额外空间。'],
 os:['先分清执行状态、共享资源与等待关系。','画出谁运行、谁等待、谁持有资源，再逐步检查每个事件是否改变就绪状态。'],
 rtos:['先区分任务优先级、中断优先级以及运行、就绪、阻塞。','画时间线，只从就绪任务中判断谁运行；资源等待与 CPU 抢占分开处理，核对 API 使用上下文。'],
 stm32:['先找到数据流：输入来自哪里，经过哪个外设，最终由谁读取。','按时钟、引脚、外设配置、事件和软件处理顺序检查；核对芯片系列、标志位与清除条件。'],
 protocol:['先确认信号的含义、空闲电平和双方约定。','按时间顺序画波形，标出发送变化与接收采样的时刻；不要把数据位、帧长度和有效载荷混在一起。'],
 linux:['先判断操作改变的是进程、文件描述符还是程序映像。','分别列父子进程的执行路径、返回值和共享资源；把错误返回与成功路径分开。'],
 engineering:['先区分看到的现象与尚未验证的原因。','确定可复现条件，记录关键状态，用一个最小实验逐项排除假设。'],
 network:['先区分分层、连接状态与数据边界。','沿收发路径列出每层处理，检查丢包、重传、缓冲与分帧条件。'],
 project:['先说清需求、自己负责的部分和实际验证结果。','画数据流，指出一个真实问题、定位证据和解决方法；不把没做过的部分当成自己的经历。']
};
export const questionHelp={
 'c-pointer-change-q1':{hint:'赋值左边只有 p。先判断它本身保存的是什么。',thinking:'分别给 a、b、p 列三格。右边 &b 是地址；只更新等号左边的格子，然后检查两个整数是否被写入。',wrong:['','这行没有通过 *p 写目标，不能当作把 b 的数值复制到 a。','地址赋给了 p，这行没有向 b 写入 a 的数值。','取得地址不会把对象的内容清零。'],errorStep:2},
 'c-pointer-change-q2':{hint:'左边是 *p，需要先确认 p 现在指向谁。',thinking:'先在图上从 p 沿箭头找到目标。把右边的整数写到目标格子，单独检查 p 保存的地址是否改变。',wrong:['','*p 指定所指对象，不是指针 p 本身。','题目已经指定当前目标，另一个整数不会自动跟着改变。','这是一条有效的目标赋值，不是只读取数值。'],errorStep:3},
 'c-pointer-change-q3':{hint:'同一句 *p 可以在不同的执行时刻访问不同对象。',thinking:'先沿前面的赋值追踪 p 保存的地址，再检查目标仍然存在且可以访问，最后才考虑写入。',wrong:['','变量名长度不会决定它指向谁。','机器外观不影响这段 C 代码访问的对象。','注释行数不能决定指针访问的目标。'],errorStep:1},
 'c-sizeof-q1':{hint:'题目问空间大小，先把变量的数值和类型分开。',thinking:'检查题目给定的 int 大小。sizeof 普通整数对象依据类型求大小，不是读取对象内保存的那个数。'},
 'c-dereference-q1':{hint:'先区分声明中的 * 与表达式中的 *。',thinking:'从 p 保存的地址找到目标，再判断表达式需要读取目标还是给目标写入。'},
 'c-pointer-declare-q1':{hint:'右边带有 &，取得的是位置。',thinking:'分开列出 x 的整数内容、x 的地址以及 p 保存的值；不要把三个量当作同一个量。'}
};
export function helpFor(q,l){const custom=qualityHelp[q.id]||questionHelp[q.id],depth=lessonDepth[l.id],base=moduleHints[l.module]||moduleHints.c;return {hint:custom?.hint||depth?.question||base[0],thinking:custom?.thinking||depth?.method||base[1],wrong:custom?.wrong,errorStep:custom?.errorStep};}
